#include "engine.hpp"
#include <iostream>
#include <cmath>
using namespace uaa;
void check(bool condition,const char* text){if(!condition)throw std::runtime_error(text);}
int main(int argc,char** argv){try{check(argc==3,"Expected data and test directory");Engine e(argv[1],argv[2]);check(!e.createRadarOutpost(-33.86,151.2).ok,"First base required");e.createBase("ORIGIN",50,14);e.state["nextUfo"]=100000.;auto initial=e.state;check(!e.createRadarOutpost(0,-30).ok&&e.state==initial,"Ocean rejection must not charge money");check(e.createRadarOutpost(-33.86,151.2).ok,"Construct standalone radar");check(e.state["money"].get<long long>()==initial["money"].get<long long>()-300000&&e.state["radarOutposts"][0]["ready"]==240.,"HTML price and ten-day construction");auto before=e.state;check(!e.createRadarOutpost(-33.8,151.3).ok&&e.state==before,"Duplicate radar rejected without payment");e.state["money"]=0;before=e.state;check(!e.createRadarOutpost(40,-3).ok&&e.state==before,"Insufficient money has no side effects");e.state["money"]=6000000;
 e.advance(239.5);e.state["ufos"].push_back({{"type","UNMANNED_DRONE"},{"lat",-33.86},{"lon",151.2},{"hull",100.},{"spawned",239.},{"expires",287.},{"environment","AIR"}});e.processRadarContacts(239.5,239.5);check(e.ufoContact(0).is_null(),"Unfinished radar cannot detect distant UFO");auto contact=e.advanceUntilUfoContact(1);check(!contact.empty()&&std::abs(e.state["hours"].get<double>()-240.)<1e-8&&contact[0]["base"]=="RADAR #1","Detection interrupts at exact completion boundary");
 e.save(1);Engine loaded(argv[1],argv[2]);check(loaded.load(1).ok&&loaded.state["radarOutposts"]==e.state["radarOutposts"],"Radar network persists across save/load");auto valid=readJson(fs::path(argv[2])/"save-1.json");auto corrupt=valid;corrupt["radarOutposts"][0]["ready"]=-1;writeJson(fs::path(argv[2])/"save-2.json",corrupt);before=loaded.state;check(!loaded.load(2).ok&&loaded.state==before,"Invalid radar save is rejected transactionally");valid.erase("radarOutposts");writeJson(fs::path(argv[2])/"save-3.json",valid);check(loaded.load(3).ok&&loaded.state["radarOutposts"].empty(),"Old campaign without outposts still loads");check(e.radarRange("radar")==2500,"Shared small-radar range");std::cout<<"PASS: land/first-base/funds/duplicate validation, HTML cost/time, exact completion detection, shared range, persistence and migration\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
